const lesson4BTNC=[{"file":"Q2B4.NC1.MP3","title":"Nâng cao 1","key":["C","A","B","E","D"],"transcript":["他正在跟朋友打电话。","她喜欢一边做饭一边听音乐。","我们常常去运动场踢足球。","弟弟每天下午练习跳舞。","爸爸在咖啡馆里一边喝咖啡一边工作。"],"questions":[["他正在跟谁打电话？",["老师","朋友","妈妈"],1],["她喜欢一边做饭一边做什么？",["听音乐","看电视","唱歌"],0],["我们常常去运动场做什么？",["打篮球","跑步","踢足球"],2],["弟弟每天下午练习什么？",["唱歌","跳舞","写字"],1],["爸爸在哪里工作？",["图书馆","学校","咖啡馆"],2]]},{"file":"Q2B4.NC2.MP3","title":"Nâng cao 2","key":["D","A","C","B","E"],"transcript":["女：你这个周末打算做什么？\n男：我想去图书馆借几本小说看看。","男：你昨天下午去哪儿了？我打电话你没接。\n女：不好意思，我在健身房锻炼，没带手机。","女：你看，那家新开的饭店好像很不错。\n男：是啊，我们中午去那儿吃面条吧。","男：你怎么去上班？骑车吗？\n女：不，我坐公交车，大概二十分钟。","女：晚上你想吃什么？我可以做。\n男：我想吃鱼，你会做红烧鱼吗？"],"questions":[["他周末想去图书馆做什么？",["买衣服","借小说","打电话"],1],["她为什么没接电话？",["没带手机","手机坏了","在睡觉"],0],["他们中午想吃什么？",["米饭","饺子","面条"],2],["她怎么去上班？",["骑车","坐公交车","走路"],1],["他晚上想吃什么？",["面条","牛肉","鱼"],2]]},{"file":"Q2B4.NC3.MP3","title":"Nâng cao 3","key":["B","C","A","A","C"],"transcript":["男：小姐，您想试试这件衬衫吗？我们有白色和蓝色的。\n女：我想试试蓝色的。嗯……好像有点儿大，有小一号的吗？","男：这双鞋真不错，是你新买的吗？\n女：对，昨天买的。原价800块，打折后560块。","女：你觉得这条裙子怎么样？\n男：颜色很漂亮，但是我觉得太长了，你穿中号的可能会更合适。","男：您好，我想买一件毛衣送给妈妈。\n女：您妈妈喜欢什么颜色？穿多大号的？\n男：她喜欢浅色的，应该穿大号的。","女：这件外套真好看，是什么料子的？\n男：是羊毛的，很暖和。价格是1200块。\n女：1200块？可以便宜一点吗？1000块怎么样？\n男：对不起，这已经是最低价了。"],"questions":[["她想试什么颜色的衬衫？",["白色","蓝色","红色"],1],["这双鞋打折后多少钱？",["800块","560块","1200块"],1],["他觉得裙子有什么问题？",["太长了","太短了","太贵了"],0],["他想给谁买毛衣？",["妈妈","姐姐","女朋友"],0],["外套最后的价格是多少？",["1000块","800块","1200块"],2]]}];
